   183	  @Transactional
   184	  public OrderResponse processPayment(Long orderId, PaymentRequest paymentRequest) throws ValidationException, NotFoundException, OperationNotAllowedException {
   185	    if (paymentRequest.transactionId() == null || paymentRequest.paidAt() == null) {
   186	      throw new ValidationException("INVALID_ORDER");
   187	    }
   188	
   189	    Order order = orderRepository.findByIdForUpdate(orderId)
   190	      .orElseThrow(() -> new NotFoundException("ORDER_NOT_FOUND"));
   191	
   192	    if (order.getTransactionId() != null && order.getTransactionId().equals(paymentRequest.transactionId())) {
   193	      return convertToResponse(order);
   194	    }
   195	
   196	    if (!order.getStatus().equals(OrderStatus.AWAITING_PAYMENT)) {
   197	      throw new OperationNotAllowedException("OPERATION_NOT_ALLOWED");
   198	    }
   199	
   200	    if (order.isExpiredForPayment()) {
   201	      order.cancel();
   202	      orderRepository.save(order);
   203	      createNotification(order.getCustomerCpf(), Notification.Type.ORDER_CANCELLED, orderId);
   204	      throw new OperationNotAllowedException("ORDER_EXPIRED");
   205	    }
   206	
   207	    checkStock(order);
   208	
   209	    order.markAsPaid(paymentRequest.transactionId(), paymentRequest.paidAt());
   210	    decreaseStock(order);
   211	
   212	    Customer customer = customerRepository.findByCpfForUpdate(order.getCustomerCpf());
   213	    if (customer == null) {
   214	      customer = new Customer(order.getCustomerCpf(), order.getCustomerEmail());
   215	    }
   216	
   217	    customer.addCredit(order.getSummary().getNextPurchaseCredit());
   218	    customerRepository.save(customer);
   219	
   220	    Order savedOrder = orderRepository.save(order);
   221	    createNotification(order.getCustomerCpf(), Notification.Type.PAYMENT_APPROVED, orderId);
   222	
   223	    return convertToResponse(savedOrder);
