   226	  @Transactional
   227	  public OrderResponse shipOrder(Long orderId, ShipmentRequest shipmentRequest) throws ValidationException, NotFoundException, OperationNotAllowedException {
   228	    if (shipmentRequest.trackingCode() == null) {
   229	      throw new ValidationException("INVALID_ORDER");
