   234	
   235	    if (!order.canBeShipped()) {
   236	      throw new OperationNotAllowedException("OPERATION_NOT_ALLOWED");
   237	    }
   238	
   239	    order.markAsShipped(shipmentRequest.trackingCode());
   240	    Order savedOrder = orderRepository.save(order);
   241	    createNotification(order.getCustomerCpf(), Notification.Type.ORDER_SHIPPED, orderId);
   242	
   243	    return convertToResponse(savedOrder);
