   246	  @Transactional
   247	  public OrderResponse deliverOrder(Long orderId) throws NotFoundException, OperationNotAllowedException {
   248	    Order order = orderRepository.findByIdForUpdate(orderId)
   249	      .orElseThrow(() -> new NotFoundException("ORDER_NOT_FOUND"));
   250	
   251	    if (!order.canBeDelivered()) {
