   322	  private void validateRequest(OrderRequest request) throws ValidationException {
   323	    if (request.customer() == null || request.customer().cpf() == null || request.customer().email() == null) {
   324	      throw new ValidationException("INVALID_ORDER");
   325	    }
   326	
   327	    if (request.items() == null || request.items().isEmpty()) {
